(() => {
 'use strict';const F=window.NastranFracture,$=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const pdf=(book,page)=>`https://documentation-be.hexagon.com/bundle/MSC_Nastran_2020_${book}/raw/resource/enus/MSC_Nastran_2020_${book}.pdf#page=${page}`;
 for(const [attr,book]of [['qrg','Quick_Reference_Guide'],['static','Linear_Static_Analysis_User_Guide'],['reference','Reference_Guide']])document.querySelectorAll(`[data-${attr}]`).forEach(a=>{a.href=pdf(book,a.dataset[attr]);a.target='_blank';a.rel='noopener';});
 const num=(v,n=6)=>Number(v).toLocaleString('ja-JP',{maximumFractionDigits:n});
 function text(x,y,s,size=17,anchor='middle'){return `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}">${esc(s)}</text>`;}
 function stressLab(){const K=Number($('crack-k').value),exponent=Number($('crack-r').value),r=10**exponent,sigma=K/Math.sqrt(2*Math.PI*r);$('crack-r-label').textContent=num(r,4)+' mm';$('crack-metrics').innerHTML=`<div><small>同じKⅠ</small><strong>${num(K)}</strong><span>MPa√mm</span></div><div><small>距離 r</small><strong>${num(r,4)}</strong><span>mm · r=0は対象外</span></div><div><small>前方の理論 σyy</small><strong>${num(sigma,2)}</strong><span>MPa · 近傍式による値</span></div>`;
  const x=e=>80+(e+3)*140,y=s=>250-(Math.log10(s)-1)*65;let svg='';for(let i=-3;i<=1;i++)svg+=`<path d="M${x(i)} 40V250" stroke="#e0e7f2"/>`+text(x(i),274,num(10**i,3),15);for(let e=1;e<=4;e++)svg+=`<path d="M80 ${y(10**e)}H640" stroke="#e0e7f2"/>`+text(65,y(10**e)+5,num(10**e),15,'end');const points=Array.from({length:81},(_,i)=>{const e=-3+i/20;return `${i?'L':'M'}${x(e)},${y(K/Math.sqrt(2*Math.PI*10**e))}`;}).join(' ');svg+=`<path d="${points}" stroke="#315bd0" stroke-width="3" fill="none"/><circle cx="${x(exponent)}" cy="${y(sigma)}" r="6" fill="#ce7345"/>`+text(80,27,'σyy (MPa)',16,'start')+text(640,292,'r (mm)',16,'end');$('crack-stress-chart').innerHTML=svg;
 }
 $('crack-k').addEventListener('change',stressLab);$('crack-r').addEventListener('input',stressLab);
 const pos=n=>({x:320+18*n.x,y:n.g===2?246:n.g===10?294:270-18*n.y});
 const labels={1:[351,252],2:[91,246],3:[123,61],4:[320,61],5:[523,61],6:[549,279],7:[523,487],8:[320,487],9:[123,487],10:[88,309],11:[86,187],12:[230,61],13:[410,61],14:[552,188],15:[552,368],16:[410,487],17:[230,487],18:[86,368]};
 function mesh(){let s='<text x="320" y="28" text-anchor="middle" class="mesh-small">全形CRAC2D · 内部の8三角形を模式表示</text>';const tip=pos(F.nodes[0]);for(let i=1;i<9;i++){const a=pos(F.nodes[i]),b=pos(F.nodes[i+1]);s+=`<path d="M${tip.x} ${tip.y}L${a.x} ${a.y}L${b.x} ${b.y}Z" fill="${i%2?'#edf3ff':'#e0eafb'}" stroke="#9eb4d4" stroke-width="1.5"/>`;}
  s+='<path d="M140 246L320 270L140 294" stroke="#c96e3d" stroke-width="3" fill="none"/><text x="216" y="276" text-anchor="middle" class="mesh-small">亀裂面</text><text x="320" y="526" text-anchor="middle" class="mesh-small">x,y = −10〜＋10 mm / 厚さ1 mm</text>';
  for(const n of F.nodes){const p=pos(n),[lx,ly]=labels[n.g];s+=`<g class="crack-dot" data-node="${n.g}" role="button" tabindex="0" aria-pressed="false" aria-label="G${n.g}、GRID ${n.id}、${esc(n.role)}"><title>G${n.g} = GRID ${n.id}</title><circle cx="${p.x}" cy="${p.y}" r="${n.g===1?9:7}" fill="${n.required?'#315bd0':'#7c97b8'}" stroke="white" stroke-width="2"/><text class="mesh-label" x="${lx}" y="${ly}" text-anchor="middle">G${n.g}</text></g>`;}$('crack-mesh').innerHTML=s;
 }
 function selectNode(g){const n=F.nodes[Number(g)-1];if(!n)return;$('crack-node-picker').value=String(g);document.querySelectorAll('[data-node]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.node)===n.g)));$('crack-node-detail').innerHTML=`<h3>G${n.g} → GRID ${n.id}</h3><p><b>${esc(n.role)}</b></p><code>(${n.x}, ${n.y}, 0) mm</code><p>${n.required?'全形では必須の節点です。':'任意の外周中間節点。この例では使います。'}</p>${n.g===1?'<p>先端のX・Yは自由です。外周条件に対する変位をNastranが解きます。</p>':`<p>外周へ与える変位：<br>ux ≈ ${num(n.ux,9)} mm<br>uy ≈ ${num(n.uy,9)} mm</p><small>BDFの指定値：ux=${F.real(n.ux)}、uy=${F.real(n.uy)}。これは入力する値で、ソルバーの結果ではありません。</small>`}${[2,10].includes(n.g)?'<p><b>G2とG10は同じ座標・別ID。</b>上側には正、下側には負の開口変位を与えます。</p>':''}`;
 }
 $('crack-node-picker').innerHTML=F.nodes.map(n=>`<option value="${n.g}">G${n.g} · GRID ${n.id} · ${esc(n.role)}</option>`).join('');$('crack-node-picker').addEventListener('change',()=>selectNode($('crack-node-picker').value));$('crack-mesh').addEventListener('click',e=>{const n=e.target.closest('[data-node]');if(n)selectNode(n.dataset.node);});$('crack-mesh').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){const n=e.target.closest('[data-node]');if(n){e.preventDefault();selectNode(n.dataset.node);}}});
 $('crack-controls-code').textContent=[...F.executive,...F.control,'BEGIN BULK'].join('\n');$('crack-raw').textContent=F.deck;
 function fieldLink(card,line,i,label){if(F.cards[card])return '#crack-field-'+card+'-'+line+'-'+i;const field=i===9?'次行':i===0?'':label==='未使用'?'空欄':label;return 'bulk.html#'+card+(field?'/'+encodeURIComponent(field):'');}
 function renderRows(){const part=$('crack-table-part').value,groups={new:['ADUM8','CRAC2D','PRAC2D'],nodes:['GRID'],constraints:['SPC','SPC1'],material:['PARAM','MAT1']};const rows=F.rows.filter(r=>part==='all'||groups[part].includes(r.card));$('crack-fields').innerHTML=rows.map(r=>{const labels=F.schemas[r.card][r.line];return `<div class="nf-card" data-card="${r.card}"><div class="nf-caption"><strong><a href="${F.cards[r.card]?'#crack-card-'+r.card:'bulk.html#'+r.card}">${r.card}</a></strong><span>${r.line?'継続行 '+r.line:''}</span></div><div class="nf-scroll" tabindex="0" aria-label="${r.card}の8文字フィールド表。横にスクロールできます"><table class="nf-table"><thead><tr>${labels.map((label,i)=>`<th scope="col"><small>第${i+1}欄</small><span>${i*8+1}–${i*8+8}列</span><b><a href="${fieldLink(r.card,r.line,i,label)}">${esc(label)}</a></b></th>`).join('')}</tr></thead><tbody><tr>${labels.map((_,i)=>{const v=r.text.slice(i*8,i*8+8);return `<td data-value="${esc(v)}"${v.trim()?'':' class="nf-empty"'}>${v.trim()?`<code>${esc(v)}</code>`:'<span aria-label="8文字分の空欄">空欄</span>'}</td>`;}).join('')}</tr></tbody></table></div></div>`;}).join('')+(part==='all'?'<div class="nf-end"><code>ENDDATA</code><span>Bulk Dataの終わり</span></div>':'');}
 $('crack-table-part').addEventListener('change',renderRows);
 function card(name){const c=F.cards[name];if(!c)return;$('crack-card-picker').value=name;$('crack-card-detail').innerHTML=`<article class="field-detail crack-field-detail" id="crack-card-${name}"><div class="eyebrow">${name}</div><h3>${esc(c.title)}</h3><p>${esc(c.intro)}</p><a href="${pdf('Quick_Reference_Guide',c.page)}" target="_blank" rel="noopener">原典QRG PDF ${c.page} ↗</a>${c.lines.map((row,line)=>`<h3>${line?'継続行 '+line:'基本行'}</h3><dl class="field-list">${row.map((f,i)=>`<div class="field-row" id="crack-field-${name}-${line}-${i}"><dt>${esc(f.label)}<span>第${i+1}欄 · ${i*8+1}–${i*8+8}列</span></dt><dd>${esc(f.help)}</dd></div>`).join('')}</dl>`).join('')}</article>`;}
 $('crack-card-picker').innerHTML=Object.entries(F.cards).map(([n,c])=>`<option value="${n}">${n} · ${esc(c.title)}</option>`).join('');$('crack-card-picker').addEventListener('change',()=>location.hash='crack-card-'+$('crack-card-picker').value);
 function route(){const m=/^#crack-(?:card|field)-(ADUM8|CRAC2D|PRAC2D)(?:-\d+-\d+)?$/.exec(location.hash);if(m){card(m[1]);requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({block:'start'}));}}
 let timer;function toast(s){$('crack-toast').textContent=s;$('crack-toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('crack-toast').hidden=true,4000);}
 $('save-crack').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([F.deck],{type:'text/plain;charset=us-ascii'})),a=document.createElement('a');a.href=url;a.download=F.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('copy-crack').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(F.deck);toast('完成BDFをコピーしました');}catch{toast('コピーできませんでした。「BDFを保存」を使ってください');}});
 mesh();selectNode(1);stressLab();renderRows();card('CRAC2D');window.addEventListener('hashchange',route);route();
})();
